  check('B8b: dahil dairelerin TUMU 0 paylıysa hata yok: satir yok, toplam 0 (NOTHING_TO_POST), zero_amount_count 2', allZero.lines.length === 0 && allZero.total === 0n && allZero.zeroAmountCount === 2 && allZero.missing.length === 0);
