    fs.writeFileSync(path.join(bumpDir, 'privacy.md'), fs.readFileSync(path.join(bumpDir, 'privacy.md'), 'utf8').replace(/^version: 2026-10-16$/m, 'version: 2026-11-01'));
    process.env.LEGAL_DIR = bumpDir;
